from pathlib import Path
import sys

path = Path(sys.argv[1])
html = path.read_text(encoding='utf-8')

old_steps = """const steps = [
  {cat:'storage',uk:['Почнемо з Хранилища','Ніночко, починай звідси. Тут має бути сума, яка приблизно збігається з тим, що зараз є на рахунку. Прийшли гроші — додай сюди. Це наша відправна точка.'],ru:['Начнём с Хранилища','Ниночка, начинай отсюда. Здесь должна быть сумма, которая примерно совпадает с тем, что сейчас есть на счёте. Пришли деньги — добавь сюда. Это наша отправная точка.']},
  {cat:'pencil',uk:['Потім — план місяця','Перевір квартиру, комуналку, школу Нікочки та інші обов’язкові витрати. Нижче — чотири окремі тижні. Для кожного можна задати свій фонд. Усе Хранилище розподіляти не треба — решта залишається резервом. Валюту вибирай поруч із сумою.'],ru:['Потом — план месяца','Проверь квартиру, коммуналку, школу Никочки и другие обязательные расходы. Ниже — четыре отдельные недели. Для каждой можно задать свой фонд. Всё Хранилище распределять не надо — остаток остаётся резервом. Валюту выбирай рядом с суммой.']},
  {cat:'weekly',uk:['Протягом тижня','Просто записуй витрати в потрібний тиждень. Витратили менше — залишок піде у «В плюс» і Хранилище. Перебрали — різниця спишеться з Хранилища, а фонд наступного тижня не зміниться. Якщо десь помилилася — запис можна відредагувати.'],ru:['В течение недели','Просто записывай траты в нужную неделю. Потратили меньше — остаток уйдёт в «В плюс» и Хранилище. Перебрали — разница спишется из Хранилища, а фонд следующей недели не изменится. Если где-то ошиблась — запись можно отредактировать.']},
  {cat:'sleeping',final:true,uk:['І ще дещо ❤️','Ніночко, просто щоб ти знала: я тебе люблю. Дуже. ❤️'],ru:['И ещё кое-что ❤️','Ниночка, просто чтобы ты знала: я тебя люблю. Очень. ❤️']}
];"""

new_steps = """const steps = [
  {cat:'storage',uk:['Головна: тут усе починається','Після входу відкриється «Головна». Угорі — Хранилище: скільки грошей зараз реально є на рахунку. Нижче побачиш «В плюс», обов’язкові витрати та чотири тижні. Спочатку натисни «Додати / відняти» й внеси поточний баланс.'],ru:['Главная: здесь всё начинается','После входа откроется «Главная». Сверху — Хранилище: сколько денег сейчас реально есть на счёте. Ниже увидишь «В плюс», обязательные расходы и четыре недели. Сначала нажми «Добавить / вычесть» и внеси текущий баланс.']},
  {cat:'pencil',uk:['План: обов’язкове та 4 тижні','Унизу натисни «План». Перевір Житло, Навчання та інші обов’язкові витрати, потім задай фонд для кожного з чотирьох тижнів. Усе Хранилище розподіляти не потрібно — те, що залишиться, буде резервом. Валюту можна вибрати біля кожної суми.'],ru:['План: обязательное и 4 недели','Внизу нажми «План». Проверь Жильё, Учёбу и другие обязательные расходы, затем задай фонд для каждой из четырёх недель. Всё Хранилище распределять не нужно — то, что останется, будет резервом. Валюту можно выбрать возле каждой суммы.']},
  {cat:'weekly',uk:['Витрати: що відбувається протягом місяця','У «Витратах» вибери потрібний тиждень і натисни «+ Додати»: категорія, сума та валюта. На екрані тижня завжди видно «Фонд», «Витрачено» та «Залишилось». Після закриття тижня залишок піде у «В плюс» і Хранилище, а перевитрата — зніметься з Хранилища. Фонд наступного тижня не зміниться. У «Ще» — мова, тема, курси та резервна копія.'],ru:['Расходы: что происходит в течение месяца','В «Расходах» выбери нужную неделю и нажми «+ Добавить»: категория, сумма и валюта. На экране недели всегда видно «Фонд», «Потрачено» и «Осталось». После закрытия недели остаток уйдёт в «В плюс» и Хранилище, а перерасход — спишется из Хранилища. Фонд следующей недели не изменится. В «Ещё» — язык, тема, курсы и резервная копия.']},
  {cat:'sleeping',final:true,uk:['І останнє ❤️','Ніночко, просто нагадаю: я тебе люблю. Дуже. ❤️'],ru:['И последнее ❤️','Ниночка, просто напомню: я тебя люблю. Очень. ❤️']}
];"""

if old_steps not in html:
    raise SystemExit('tutorial block not found')
html = html.replace(old_steps, new_steps)

anchor = "const RUSSIAN = {\n  'Мова й вигляд':'Язык и оформление',"
insert = """const RUSSIAN = {
  'Мова й вигляд':'Язык и оформление',
  'Головна':'Главная','Витрати':'Расходы','План':'План','Аналітика':'Аналитика','Ще':'Ещё',
  'Наш спільний баланс':'Наш общий баланс','Дім':'Дом','+ Додати':'+ Добавить',
  'Дата надходження':'Дата поступления','Категорія':'Категория','Назва категорії':'Название категории',
  'Це навчання завжди можна відкрити ще раз у налаштуваннях.':'Эту подсказку всегда можно снова открыть в настройках.',
  'Збережено історичний курс. Зміна суми його не змінює.':'Сохранён исторический курс. Изменение суммы его не меняет.',
  'До 8 знаків після коми. Курс буде позначено як ручний.':'До 8 знаков после запятой. Курс будет сохранён как ручной.',
"""
if anchor not in html:
    raise SystemExit('translation anchor not found')
html = html.replace(anchor, insert)

html = html.replace("'Збережено за весь час':'Сэкономлено за всё время'", "'Збережено за весь час':'Всего сохранено'")
html = html.replace("'Окремо від сімейного бюджету':'Отдельно от семейного бюджета'", "'Окремо від сімейного бюджету':'Не влияет на семейный бюджет'")
html = html.replace("'Поточний баланс вашого банку':'Текущий баланс вашего банка'", "'Поточний баланс вашого банку':'Текущий остаток на банковском счёте'")

path.write_text(html, encoding='utf-8')
print('Patched onboarding and Russian UI text')
